// Rust guideline compliant 2026-02-21
use gpui_mesh::{CellType, Cells, DataSet, Field};
use gpui_profiler::AllocProbe;
use gpui_scene3d::{Actor, Camera, GpuChunk, GpuRenderer, Scene, TransferFunction, prepare_chunks};
use std::{hint::black_box, time::Instant};
fn cpu_ns() -> u128 {
    let mut stamp = libc::timespec {
        tv_sec: 0,
        tv_nsec: 0,
    };
    // SAFETY: stamp is valid writable storage for this synchronous clock call,
    // which retains no pointer. Its status and returned timestamp are checked.
    let result = unsafe { libc::clock_gettime(libc::CLOCK_PROCESS_CPUTIME_ID, &mut stamp) };
    assert_eq!(result, 0);
    assert!(stamp.tv_sec >= 0 && (0..1_000_000_000).contains(&stamp.tv_nsec));
    stamp.tv_sec as u128 * 1_000_000_000 + stamp.tv_nsec as u128
}

fn hash(bytes: &[u8]) -> u64 {
    bytes.iter().fold(0xcbf29ce484222325, |h, &v| {
        (h ^ u64::from(v)).wrapping_mul(0x100000001b3)
    })
}
fn chunk_hash(chunks: &[GpuChunk]) -> u64 {
    let mut bytes = Vec::new();
    for c in chunks {
        for v in c.positions.iter().chain(&c.normals).chain(&c.scalars) {
            bytes.extend(v.to_bits().to_le_bytes());
        }
        for v in c.indices.iter().chain(&c.edges) {
            bytes.extend(v.to_le_bytes());
        }
    }
    hash(&bytes)
}
fn scene(kind: &str, n: usize, encoded: bool) -> Scene {
    let (lo, hi) = if encoded { (1e100, 2e100) } else { (0.0, 1.0) };
    let (mut data, association) = if kind == "line" || kind == "point_primitive" {
        let line = kind == "line";
        let arity = if line { 2 } else { 1 };
        (
            DataSet::new(
                "primitives",
                if line {
                    vec![[-0.5, 0.0, 0.0], [0.5, 0.0, 0.0]]
                } else {
                    vec![[0.0; 3]]
                },
                Cells {
                    types: vec![
                        if line {
                            CellType::Line
                        } else {
                            CellType::Vertex
                        };
                        n
                    ]
                    .into(),
                    offsets: (0..=n)
                        .map(|i| (i * arity) as u64)
                        .collect::<Vec<_>>()
                        .into(),
                    connectivity: (0..n * arity)
                        .map(|i| (i % arity) as u32)
                        .collect::<Vec<_>>()
                        .into(),
                },
            ),
            false,
        )
    } else {
        let mut d =
            DataSet::structured_grid("surface", [n; 3], [-1.0; 3], [2.0 / (n - 1) as f64; 3])
                .unwrap();
        if kind == "general" {
            let nodes = std::sync::Arc::make_mut(&mut d.cells.connectivity);
            let last = nodes.len() - 8;
            nodes[last..last + 4].rotate_left(1);
            nodes[last + 4..].rotate_left(1);
        }
        (d, kind == "cell")
    };
    let field = if association {
        Field::scalar(
            "p",
            (0..data.cells.types.len())
                .map(|i| lo + (hi - lo) * (0.25 + 0.5 * (i % 2) as f64))
                .collect::<Vec<_>>(),
        )
        .on_cells()
    } else {
        Field::scalar(
            "p",
            if kind == "line" {
                vec![lo, hi]
            } else if kind == "gradient" {
                data.positions
                    .iter()
                    .map(|p| lo + (hi - lo) * ((p[0] + 1.0) * 0.5))
                    .collect()
            } else {
                vec![lo + (hi - lo) * 0.5; data.positions.len()]
            },
        )
    };
    data = data.with_field(field);
    let actor = if association {
        Actor::new(data).coloured_by_cell("p", TransferFunction::viridis([lo, hi]))
    } else {
        Actor::new(data).coloured_by("p", TransferFunction::viridis([lo, hi]))
    };
    Scene::new().with_actor(actor)
}
#[derive(Default)]
struct Samples {
    cpu: Vec<u128>,
    wall: Vec<u128>,
    calls: Vec<usize>,
    bytes: Vec<usize>,
}
impl Samples {
    fn call<T>(&mut self, run: impl FnOnce() -> T) -> T {
        let mut p = AllocProbe::new();
        let cpu = cpu_ns();
        let t = Instant::now();
        let out = black_box(run());
        let wall = t.elapsed().as_nanos();
        let cpu = cpu_ns() - cpu;
        let a = p.sample("scalar-transport");
        self.cpu.push(cpu);
        self.wall.push(wall);
        self.calls.push(a.count);
        self.bytes.push(a.bytes);
        out
    }
    fn emit(&self, kind: &str, n: usize, encoded: bool, op: &str, payload: u64, image: u64) {
        println!(
            r#"{{"kind":"{kind}","n":{n},"encoded":{encoded},"op":"{op}","payload_bytes":{payload},"image_hash":"{image:016x}","cpu_ns":{:?},"wall_ns":{:?},"allocation_calls":{:?},"allocated_bytes":{:?},"chunk_metadata_bytes":{},"allocator":{}}}"#,
            self.cpu,
            self.wall,
            self.calls,
            self.bytes,
            std::mem::size_of::<GpuChunk>(),
            cfg!(feature = "allocations")
        );
    }
}
fn measure<T>(
    kind: &str,
    n: usize,
    encoded: bool,
    op: &str,
    payload: u64,
    image: u64,
    mut run: impl FnMut() -> T,
    mut check: impl FnMut(T),
) {
    check(run());
    let mut s = Samples::default();
    for _ in 0..5 {
        let result = s.call(&mut run);
        check(result);
    }
    s.emit(kind, n, encoded, op, payload, image)
}
fn exercise(renderer: &GpuRenderer, kind: &str, n: usize, encoded: bool) {
    let expected_rebuild = encoded && std::env::args().any(|a| a == "--baseline-rebuild");
    let mut scene = scene(kind, n, encoded);
    if kind == "gradient" {
        let (_, values) = scene.actors[0].scalars().unwrap();
        let minimum = values.iter().copied().fold(f64::INFINITY, f64::min);
        let maximum = values.iter().copied().fold(f64::NEG_INFINITY, f64::max);
        assert!(minimum < maximum && values.iter().any(|v| *v > minimum && *v < maximum));
    }
    let camera = Camera::fitted(scene.bounds().unwrap());
    let target = renderer.create_target(64, 64).unwrap();
    if kind != "line" && kind != "point_primitive" {
        let chunks = prepare_chunks(&scene.actors[0], 1_000_000).unwrap();
        let payload = chunks.iter().map(GpuChunk::byte_len).sum();
        let h = chunk_hash(&chunks);
        measure(
            kind,
            n,
            encoded,
            "prepare",
            payload,
            h,
            || prepare_chunks(&scene.actors[0], 1_000_000).unwrap(),
            |out| {
                assert_eq!(out.iter().map(GpuChunk::byte_len).sum::<u64>(), payload);
                assert_eq!(chunk_hash(&out), h);
            },
        );
    }
    let expected = gpui_scene3d::render(&scene, &camera, 64, 64).unwrap();
    let prepared_payload = scene.prepare().unwrap().byte_len();
    let mut cache_samples = Samples::default();
    for sample in 0..6 {
        // Clear/drop outside the clock. Time the real scene-owned cold cache,
        // including its validation, extraction and compatibility bookkeeping.
        scene.clear_preparation();
        let prepared = if sample == 0 {
            scene.prepare().unwrap()
        } else {
            cache_samples.call(|| scene.prepare().unwrap())
        };
        assert_eq!(prepared.byte_len(), prepared_payload);
        assert_eq!(gpui_scene3d::render(&scene, &camera, 64, 64).unwrap(), expected);
    }
    cache_samples.emit(kind, n, encoded, "cache_prepare", prepared_payload, hash(&expected.rgba));
    assert!(
        expected
            .rgba
            .as_chunks::<4>()
            .0
            .iter()
            .any(|p| p[0] != p[1])
    );
    measure(
        kind,
        n,
        encoded,
        "software",
        prepared_payload,
        hash(&expected.rgba),
        || gpui_scene3d::render(&scene, &camera, 64, 64).unwrap(),
        |out| assert_eq!(out, expected),
    );
    let mut resident = renderer.upload(&scene).unwrap();
    let payload = resident.geometry_bytes;
    renderer.render(&mut resident, &camera, &target).unwrap();
    let image = renderer.read_rgba(&target).unwrap();
    measure(
        kind,
        n,
        encoded,
        "upload",
        payload,
        hash(&image.rgba),
        || renderer.upload(&scene).unwrap(),
        |mut out| {
            assert_eq!(out.geometry_bytes, payload);
            renderer.render(&mut out, &camera, &target).unwrap();
            assert_eq!(renderer.read_rgba(&target).unwrap(), image)
        },
    );
    measure(
        kind,
        n,
        encoded,
        "submit",
        payload,
        hash(&image.rgba),
        || renderer.render(&mut resident, &camera, &target).unwrap(),
        |()| assert_eq!(renderer.read_rgba(&target).unwrap(), image),
    );
    let base = scene.actors[0].transfer.as_ref().unwrap().range;
    let alternate = [base[0], base[0] + (base[1] - base[0]) * 2.0];
    let mut other = Scene::new().with_actor(scene.actors[0].clone());
    other.actors[0].transfer.as_mut().unwrap().range = alternate;
    let mut second = renderer.upload(&other).unwrap();
    renderer.render(&mut second, &camera, &target).unwrap();
    let alternate_image = renderer.read_rgba(&target).unwrap();
    let mut samples = Samples::default();
    let mut changed = false;
    for sample in 0..6 {
        changed = !changed;
        scene.actors[0].transfer.as_mut().unwrap().range = if changed { alternate } else { base };
        let mut update = || renderer.sync(&mut resident, &scene).unwrap();
        let rebuilt = if sample == 0 {
            update()
        } else {
            samples.call(update)
        };
        assert_eq!(rebuilt, expected_rebuild);
        renderer.render(&mut resident, &camera, &target).unwrap();
        assert_eq!(
            renderer.read_rgba(&target).unwrap(),
            if changed {
                alternate_image.clone()
            } else {
                image.clone()
            }
        );
    }
    samples.emit(kind, n, encoded, "range_update", payload, hash(&image.rgba));
    assert!(!changed);
}
fn main() {
    let args: Vec<_> = std::env::args().collect();
    let encoded = args.get(1).is_some_and(|v| v == "--normalized");
    if args.get(1).is_some_and(|v| v == "--rss") {
        let kind = &args[2];
        let n = args[3].parse().unwrap();
        let encoded = args[4] == "normalized";
        let scene = scene(kind, n, encoded);
        let chunks = prepare_chunks(&scene.actors[0], 1_000_000).unwrap();
        println!(
            "{} {:016x}",
            chunks.iter().map(GpuChunk::byte_len).sum::<u64>(),
            chunk_hash(&chunks)
        );
        return;
    }
    if args.get(1).is_some_and(|v| v == "--cpu-prepare") {
        let kind = &args[2];
        let n = args[3].parse().unwrap();
        let encoded = args[4] == "normalized";
        let scene = scene(kind, n, encoded);
        let chunks = prepare_chunks(&scene.actors[0], 1_000_000).unwrap();
        let payload = chunks.iter().map(GpuChunk::byte_len).sum();
        let geometry = chunk_hash(&chunks);
        let camera = Camera::fitted(scene.bounds().unwrap());
        let expected = gpui_scene3d::render(&scene, &camera, 64, 64).unwrap();
        drop(chunks);
        measure(kind, n, encoded, "prepare", payload, geometry,
            || prepare_chunks(&scene.actors[0], 1_000_000).unwrap(),
            |chunks| {
                assert_eq!(chunks.iter().map(GpuChunk::byte_len).sum::<u64>(), payload);
                assert_eq!(chunk_hash(&chunks), geometry);
            });
        let mut cache = Samples::default();
        for sample in 0..6 {
            scene.clear_preparation();
            let prepared = if sample == 0 { scene.prepare().unwrap() }
                else { cache.call(|| scene.prepare().unwrap()) };
            assert_eq!(prepared.byte_len(), payload);
            assert_eq!(gpui_scene3d::render(&scene, &camera, 64, 64).unwrap(), expected);
        }
        cache.emit(kind, n, encoded, "cache_prepare", payload, hash(&expected.rgba));
        return;
    }
    let renderer = GpuRenderer::new(wgpu::TextureFormat::Rgba8Unorm).unwrap();
    for kind in if encoded {
        vec!["point", "cell", "gradient"]
    } else {
        vec!["point", "cell", "gradient", "general"]
    } {
        for n in [16, 48] {
            exercise(&renderer, kind, n, encoded)
        }
    }
    if !encoded {
        for kind in ["line", "point_primitive"] {
            for n in [256, 65536] {
                exercise(&renderer, kind, n, false)
            }
        }
    }
}

